using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Org.OpenAPITools.Client;
using Org.OpenAPITools.Model;
using Xunit;

namespace Org.OpenAPITools.Test.Client
{
    /// <summary>
    /// Regression tests for deserializing oneOf/anyOf responses (types derived from
    /// AbstractOpenAPISchema) in the httpclient library.
    /// See https://github.com/OpenAPITools/openapi-generator/issues/25079
    /// </summary>
    public class OneOfResponseDeserializationTests
    {
        /// <summary>
        /// Returns a canned JSON body for every request, so ExecAsync can be exercised
        /// without a live server.
        /// </summary>
        private sealed class StubHttpMessageHandler : HttpMessageHandler
        {
            private readonly string _json;

            public StubHttpMessageHandler(string json)
            {
                _json = json;
            }

            protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
            {
                var response = new HttpResponseMessage(HttpStatusCode.OK)
                {
                    Content = new StringContent(_json, Encoding.UTF8, "application/json")
                };
                return Task.FromResult(response);
            }
        }

        /// <summary>
        /// A oneOf/anyOf response must be deserialized via the model's static
        /// FromJson(string) method. Previously ApiClient.ExecAsync passed the
        /// HttpContent instead of the body string, which threw an ArgumentException
        /// at runtime for every oneOf/anyOf response.
        /// </summary>
        [Fact]
        public async Task OneOfResponseIsDeserializedToConcreteType()
        {
            var httpClient = new HttpClient(new StubHttpMessageHandler("{\"className\":\"BasquePig\"}"));
            var apiClient = new ApiClient(httpClient, "http://localhost");

            ApiResponse<Pig> response = await apiClient.GetAsync<Pig>("/fake", new RequestOptions());

            Assert.NotNull(response.Data);
            Assert.IsType<BasquePig>(response.Data.ActualInstance);
        }
    }
}
